    public static class LauncherPhoto {
        public static BitmapSource Load(string file) {try{if(!File.Exists(file)||new FileInfo(file).Length>4*1024*1024)return null;using(var stream=File.OpenRead(file)){var decoder=BitmapDecoder.Create(stream,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);var frame=decoder.Frames[0];if(frame.PixelWidth>8192||frame.PixelHeight>8192)throw new IOException("Choose a photo up to 8192 pixels.");int side=Math.Min(frame.PixelWidth,frame.PixelHeight);var crop=new CroppedBitmap(frame,new Int32Rect((frame.PixelWidth-side)/2,(frame.PixelHeight-side)/2,side,side));var scaled=new TransformedBitmap(crop,new ScaleTransform(128.0/side,128.0/side));scaled.Freeze();return scaled;}}catch{return null;}}
        public static void Save(string file,BitmapSource image) {if(image==null){if(File.Exists(file))File.Delete(file);return;}Directory.CreateDirectory(Path.GetDirectoryName(file));var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));string temp=file+".tmp";using(var output=File.Create(temp))encoder.Save(output);if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}
    }
